// Hourly sweep for open issues.
// Current assignee is the source of truth for activation.
const SK = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InR3dGhnYXBpb3VpcWhhdnJjbnJ5Iiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc3NDUzMTY3NiwiZXhwIjoyMDkwMTA3Njc2fQ.EyNdtvECdcHx3RuaizdfLGNRY4OJotzjE2QeOQ9Yf4Q';
const SUPA = 'https://twthgapiouiqhavrcnry.supabase.co';
const h = { apikey: SK, Authorization: 'Bearer ' + SK };
const TRIGGER_URL = 'http://127.0.0.1:8787/trigger-agent';
const DEDUPE_TTL_MS = 55 * 60 * 1000;

const AGENT_MAP = {
  'tester': 'tester', 'builder': 'builder', 'scout': 'scout', 'ops': 'ops',
  'kemuni-sme': 'kemuni-sme', 'vespera-sme': 'vespera-sme', 'main': 'main', 'KAOS': 'main',
  'po': 'po', 'designer': 'designer', 'auditor': 'auditor', 'deployer': 'deployer', 'ux': 'designer',
};

const staticData = $getWorkflowStaticData('global');
if (!staticData.triggered) staticData.triggered = {};
const now = Date.now();
for (const [key, ts] of Object.entries(staticData.triggered)) {
  if (now - ts > DEDUPE_TTL_MS) delete staticData.triggered[key];
}

const issues = await helpers.httpRequest({
  method: 'GET',
  url: SUPA + '/rest/v1/issues?status=eq.open&select=id,task_key,title,assignee,status',
  headers: h
});

const results = [];
for (const issue of issues) {
  const agentId = issue.assignee ? AGENT_MAP[issue.assignee] : null;
  const dedupeKey = `${issue.id}:${issue.assignee || 'unassigned'}:${issue.status}`;
  if (staticData.triggered[dedupeKey]) continue;
  if (!agentId) {
    results.push({ key: issue.task_key, action: 'skipped', reason: `no agent for ${issue.assignee || 'unassigned'}` });
    continue;
  }

  const message = `Issue ${issue.task_key} is open and assigned to you: ${issue.title}. Pick it up and start work.`;
  try {
    await helpers.httpRequest({
      method: 'POST',
      url: TRIGGER_URL,
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ agentId, message })
    });
    staticData.triggered[dedupeKey] = now;
    results.push({ key: issue.task_key, agent: agentId, action: 'activated' });
  } catch (e) {
    results.push({ key: issue.task_key, agent: agentId, action: 'error', reason: e.message });
  }
}

return [{ json: { processed: results.length, results, timestamp: new Date().toISOString() } }];
